-- Selected from the public-domain free-exercise-db snapshot f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5.
-- FiFB classifies movement, required apparatus and duration for two sets with rest.
SET LOCAL search_path TO "${flyway:defaultSchema}", pg_catalog;
CREATE TEMP TABLE core_seed (
  source_id text PRIMARY KEY, name text, pattern text, difficulty int, exercise_type text,
  muscle text, gear text[], instructions jsonb
) ON COMMIT DROP;

SELECT 'fifb-core:'||source_id,'admin',name,instructions,
       jsonb_build_object('dataset','free-exercise-db','source_id',source_id,'revision','f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5')
FROM core_seed;

SELECT e.id,g.id FROM core_seed s JOIN exercises e ON e.external_id='fifb-core:'||s.source_id
JOIN equipments g ON g.name=ANY(s.gear);
SELECT e.id,m.id,'target' FROM core_seed s JOIN exercises e ON e.external_id='fifb-core:'||s.source_id
JOIN muscles m ON m.name=s.muscle;
  estimated_minutes,replacement_group,classification_confidence,review_status)
SELECT e.id,s.pattern,s.difficulty,s.exercise_type,s.difficulty=1,
  CASE WHEN s.pattern='core' THEN 3 WHEN s.difficulty=1 THEN 4 ELSE 5 END,
  s.pattern,'high','approved' FROM core_seed s JOIN exercises e ON e.external_id='fifb-core:'||s.source_id;
