INSERT INTO core_seed VALUES
('Bodyweight_Squat', 'Bodyweight Squat', 'squat', 1, 'strength', 'quadriceps', ARRAY['body weight'], '["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.", "Begin the movement by flexing your knees and hips, sitting back with your hips.", "Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."]'::jsonb),
('Dumbbell_Squat', 'Dumbbell Squat', 'squat', 1, 'strength', 'quadriceps', ARRAY['dumbbell'], '["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).", "Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.", "Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Goblet_Squat', 'Goblet Squat', 'squat', 1, 'strength', 'quadriceps', ARRAY['kettlebell'], '["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.", "Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.", "At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."]'::jsonb),
('Hack_Squat', 'Hack Squat', 'squat', 1, 'strength', 'quadriceps', ARRAY['hack squat machine'], '["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.", "Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.", "Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).", "Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Barbell_Squat', 'Barbell Squat', 'squat', 2, 'strength', 'quadriceps', ARRAY['barbell','rack'], '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Barbell_Full_Squat', 'Barbell Full Squat', 'squat', 2, 'strength', 'quadriceps', ARRAY['barbell','rack'], '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.", "Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.", "Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Plie_Dumbbell_Squat', 'Plie Dumbbell Squat', 'squat', 1, 'strength', 'quadriceps', ARRAY['dumbbell'], '["Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.", "Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.", "Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.", "Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Squats_-_With_Bands', 'Squats - With Bands', 'squat', 1, 'strength', 'quadriceps', ARRAY['bands'], '["To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.", "When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.", "Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.", "Use the heel of your feet to push your body up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Butt_Lift_Bridge', 'Butt Lift (Bridge)', 'hinge', 1, 'strength', 'glutes', ARRAY['body weight'], '["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.", "Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.", "Slowly go back to the starting position as you breathe in."]'::jsonb),
('Single_Leg_Glute_Bridge', 'Single Leg Glute Bridge', 'hinge', 1, 'strength', 'glutes', ARRAY['body weight'], '["Lay on the floor with your feet flat and knees bent.", "Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.", "Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.", "Extend as far as possible, pause and then return to the starting position."]'::jsonb),
('Barbell_Glute_Bridge', 'Barbell Glute Bridge', 'hinge', 2, 'strength', 'glutes', ARRAY['barbell'], '["Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.", "Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.", "Extend as far as possible, then reverse the motion to return to the starting position."]'::jsonb),
('Romanian_Deadlift', 'Romanian Deadlift', 'hinge', 2, 'strength', 'hamstrings', ARRAY['barbell'], '["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.", "Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.", "Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.", "Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Barbell_Deadlift', 'Barbell Deadlift', 'hinge', 2, 'strength', 'lower back', ARRAY['barbell'], '["Stand in front of a loaded barbell.", "While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.", "While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.", "Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.", "Perform the amount of repetitions prescribed in the program."]'::jsonb),
('Stiff-Legged_Dumbbell_Deadlift', 'Stiff-Legged Dumbbell Deadlift', 'hinge', 1, 'strength', 'hamstrings', ARRAY['dumbbell'], '["Grasp a couple of dumbbells holding them by your side at arm''s length.", "Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.", "Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement", "Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Cable_Deadlifts', 'Cable Deadlifts', 'hinge', 1, 'strength', 'quadriceps', ARRAY['cable'], '["Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.", "To begin, squat down be flexing your hips and knees until you can reach the handles.", "After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.", "After reaching a full standing position, Return to the starting position and repeat."]'::jsonb),
('Sumo_Deadlift', 'Sumo Deadlift', 'hinge', 2, 'strength', 'hamstrings', ARRAY['barbell'], '["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.", "Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.", "As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.", "Return the weight to the ground by bending at the hips and controlling the weight on the way down."]'::jsonb),
('Pushups', 'Pushups', 'horizontal_push', 1, 'strength', 'chest', ARRAY['body weight'], '["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.", "Next, lower yourself downward until your chest almost touches the floor as you inhale.", "Now breathe out and press your upper body back up to the starting position while squeezing your chest.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."]'::jsonb),
('Push-Up_Wide', 'Push-Up Wide', 'horizontal_push', 1, 'strength', 'chest', ARRAY['body weight'], '["With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.", "To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.", "Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.", "After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."]'::jsonb),
('Push-Ups_-_Close_Triceps_Position', 'Push-Ups - Close Triceps Position', 'horizontal_push', 2, 'strength', 'triceps', ARRAY['body weight'], '["Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.", "Lower yourself until your chest almost touches the floor as you inhale.", "Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]'::jsonb),
('Barbell_Bench_Press_-_Medium_Grip', 'Barbell Bench Press - Medium Grip', 'horizontal_push', 1, 'strength', 'chest', ARRAY['barbell','bench','rack'], '["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.", "After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."]'::jsonb),
('Dumbbell_Bench_Press', 'Dumbbell Bench Press', 'horizontal_push', 1, 'strength', 'chest', ARRAY['dumbbell','bench'], '["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.", "Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.", "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.", "Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions of your training program."]'::jsonb),
('Machine_Bench_Press', 'Machine Bench Press', 'horizontal_push', 1, 'strength', 'chest', ARRAY['chest press machine'], '["Sit down on the Chest Press Machine and select the weight.", "Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.", "Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.", "Now bring the handles back towards you as you breathe in.", "Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.", "Repeat for the recommended amount of reps.", "When finished step on the lever again and slowly get the handles back to their original place."]'::jsonb),
('Dumbbell_Bench_Press_with_Neutral_Grip', 'Dumbbell Bench Press with Neutral Grip', 'horizontal_push', 1, 'strength', 'chest', ARRAY['dumbbell','bench'], '["Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.", "Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.", "Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.", "Pause, then extend the elbow and return to the starting position."]'::jsonb),
('Incline_Push-Up', 'Incline Push-Up', 'horizontal_push', 1, 'strength', 'chest', ARRAY['bench'], '["Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.", "Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.", "Push body up until arms are extended. Repeat."]'::jsonb),
('Standing_Military_Press', 'Standing Military Press', 'vertical_push', 2, 'strength', 'shoulders', ARRAY['barbell','rack'], '["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.", "Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.", "Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.", "Lower the bar down to the collarbone slowly as you inhale.", "Lift the bar back up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Shoulder_Press_-_With_Bands', 'Shoulder Press - With Bands', 'vertical_push', 1, 'strength', 'shoulders', ARRAY['bands'], '["To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side.", "Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.", "As you exhale, lift the handles up until your arms are fully extended overhead."]'::jsonb),
('Alternating_Cable_Shoulder_Press', 'Alternating Cable Shoulder Press', 'vertical_push', 1, 'strength', 'shoulders', ARRAY['cable'], '["Move the cables to the bottom of the tower and select an appropriate weight.", "Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.", "Keeping your head and chest up, extend through the elbow to press one side directly over head.", "After pausing at the top, return to the starting position and repeat on the opposite side."]'::jsonb),
('Cable_Shoulder_Press', 'Cable Shoulder Press', 'vertical_push', 1, 'strength', 'shoulders', ARRAY['cable'], '["Move the cables to the bottom of the towers and select an appropriate weight.", "Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.", "Keeping your head and chest up, extend through the elbow to press the handles directly over head.", "After pausing at the top, return to the starting position and repeat."]'::jsonb),
('Leverage_Shoulder_Press', 'Leverage Shoulder Press', 'vertical_push', 1, 'strength', 'shoulders', ARRAY['shoulder press machine'], '["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.", "Press the handles upward by extending through the elbow.", "After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]'::jsonb),
('Dumbbell_One-Arm_Shoulder_Press', 'Dumbbell One-Arm Shoulder Press', 'vertical_push', 2, 'strength', 'shoulders', ARRAY['dumbbell'], '["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.", "Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.", "Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.", "As you exhale, push the dumbbell up until your arm is fully extended.", "After a second pause, slowly come down back to the starting position as you inhale.", "Repeat for the recommended amount of repetitions and then switch arms."]'::jsonb),
('Arnold_Dumbbell_Press', 'Arnold Dumbbell Press', 'vertical_push', 2, 'strength', 'shoulders', ARRAY['dumbbell','bench'], '["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.", "Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.", "Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.", "After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Two-Arm_Kettlebell_Military_Press', 'Two-Arm Kettlebell Military Press', 'vertical_push', 2, 'strength', 'shoulders', ARRAY['kettlebell'], '["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.", "Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability."]'::jsonb),
('Bent_Over_Barbell_Row', 'Bent Over Barbell Row', 'horizontal_pull', 1, 'strength', 'middle back', ARRAY['barbell'], '["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.", "Then inhale and slowly lower the barbell back to the starting position.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Bent_Over_Two-Dumbbell_Row', 'Bent Over Two-Dumbbell Row', 'horizontal_pull', 1, 'strength', 'middle back', ARRAY['dumbbell'], '["With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.", "Slowly lower the weight again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('One-Arm_Dumbbell_Row', 'One-Arm Dumbbell Row', 'horizontal_pull', 1, 'strength', 'middle back', ARRAY['dumbbell','bench'], '["Choose a flat bench and place a dumbbell on each side of it.", "Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.", "Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.", "Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.", "Lower the resistance straight down to the starting position. Breathe in as you perform this step.", "Repeat the movement for the specified amount of repetitions.", "Switch sides and repeat again with the other arm."]'::jsonb),
('One-Arm_Kettlebell_Row', 'One-Arm Kettlebell Row', 'horizontal_pull', 2, 'strength', 'middle back', ARRAY['kettlebell'], '["Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat."]'::jsonb),
('Seated_Cable_Rows', 'Seated Cable Rows', 'horizontal_pull', 1, 'strength', 'middle back', ARRAY['seated cable row machine','v-bar'], '["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.", "Lean over as you keep the natural alignment of your back and grab the V-bar handles.", "With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.", "Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Leverage_Iso_Row', 'Leverage Iso Row', 'horizontal_pull', 1, 'strength', 'lats', ARRAY['row machine'], '["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."]'::jsonb),
('Dumbbell_Incline_Row', 'Dumbbell Incline Row', 'horizontal_pull', 1, 'strength', 'middle back', ARRAY['dumbbell','bench'], '["Using a neutral grip, lean into an incline bench.", "Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.", "Retract the shoulder blades and flex the elbows to row the dumbbells to your side.", "Pause at the top of the motion, and then return to the starting position."]'::jsonb),
('Reverse_Grip_Bent-Over_Rows', 'Reverse Grip Bent-Over Rows', 'horizontal_pull', 2, 'strength', 'middle back', ARRAY['barbell'], '["Stand erect while holding a barbell with a supinated grip (palms facing up).", "Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.", "Slowly lower the weight again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Wide-Grip_Lat_Pulldown', 'Wide-Grip Lat Pulldown', 'vertical_pull', 1, 'strength', 'lats', ARRAY['lat pulldown machine'], '["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.", "After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."]'::jsonb),
('Close-Grip_Front_Lat_Pulldown', 'Close-Grip Front Lat Pulldown', 'vertical_pull', 1, 'strength', 'lats', ARRAY['lat pulldown machine','v-bar'], '["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.", "After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "6. Repeat this motion for the prescribed amount of repetitions."]'::jsonb),
('Underhand_Cable_Pulldowns', 'Underhand Cable Pulldowns', 'vertical_pull', 1, 'strength', 'lats', ARRAY['lat pulldown machine'], '["Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.", "Repeat this motion for the prescribed amount of repetitions."]'::jsonb),
('One_Arm_Lat_Pulldown', 'One Arm Lat Pulldown', 'vertical_pull', 1, 'strength', 'lats', ARRAY['lat pulldown machine','single handle'], '["Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.", "Pull the handle down, squeezing your elbow to your side as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handle to the starting position.", "For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked."]'::jsonb),
('V-Bar_Pulldown', 'V-Bar Pulldown', 'vertical_pull', 2, 'strength', 'lats', ARRAY['lat pulldown machine','v-bar'], '["Sit down on a pull-down machine with a V-Bar attached to the top pulley.", "Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.", "Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.", "After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.", "Repeat for the prescribed number of repetitions."]'::jsonb),
('Chin-Up', 'Chin-Up', 'vertical_pull', 2, 'strength', 'lats', ARRAY['pull-up bar'], '["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.", "As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."]'::jsonb),
('Pullups', 'Pullups', 'vertical_pull', 2, 'strength', 'lats', ARRAY['pull-up bar'], '["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.", "Repeat this motion for the prescribed amount of repetitions."]'::jsonb),
('Band_Assisted_Pull-Up', 'Band Assisted Pull-Up', 'vertical_pull', 1, 'strength', 'lats', ARRAY['pull-up bar','bands'], '["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.", "Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.", "Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.", "After a brief pause, return to the starting position."]'::jsonb),
('Dumbbell_Lunges', 'Dumbbell Lunges', 'single_leg', 1, 'strength', 'quadriceps', ARRAY['dumbbell'], '["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.", "Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.", "Using mainly the heel of your foot, push up and go back to the starting position as you exhale.", "Repeat the movement for the recommended amount of repetitions and then perform with the left leg."]'::jsonb),
('Dumbbell_Rear_Lunge', 'Dumbbell Rear Lunge', 'single_leg', 2, 'strength', 'quadriceps', ARRAY['dumbbell'], '["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.", "Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.", "Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.", "Now repeat with the opposite leg."]'::jsonb),
('Barbell_Lunge', 'Barbell Lunge', 'single_leg', 2, 'strength', 'quadriceps', ARRAY['barbell','rack'], '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>", "Using mainly the heel of your foot, push up and go back to the starting position as you exhale.", "Repeat the movement for the recommended amount of repetitions and then perform with the left leg."]'::jsonb),
('Barbell_Walking_Lunge', 'Barbell Walking Lunge', 'single_leg', 1, 'strength', 'quadriceps', ARRAY['barbell','rack'], '["Begin standing with your feet shoulder width apart and a barbell across your upper back.", "Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.", "Drive through the heel of your lead foot and extend both knees to raise yourself back up.", "Step forward with your rear foot, repeating the lunge on the opposite leg."]'::jsonb),
('Bodyweight_Walking_Lunge', 'Bodyweight Walking Lunge', 'single_leg', 1, 'strength', 'quadriceps', ARRAY['body weight'], '["Begin standing with your feet shoulder width apart and your hands on your hips.", "Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.", "Drive through the heel of your lead foot and extend both knees to raise yourself back up.", "Step forward with your rear foot, repeating the lunge on the opposite leg."]'::jsonb),
('Crossover_Reverse_Lunge', 'Crossover Reverse Lunge', 'single_leg', 2, 'strength', 'lower back', ARRAY['body weight'], '["Stand with your feet shoulder width apart. This will be your starting position.", "Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.", "After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."]'::jsonb),
('Split_Squat_with_Dumbbells', 'Split Squat with Dumbbells', 'single_leg', 1, 'strength', 'quadriceps', ARRAY['dumbbell','bench'], '["Position yourself into a staggered stance with the rear foot elevated and front foot forward.", "Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.", "Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.", "At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."]'::jsonb),
('Step-up_with_Knee_Raise', 'Step-up with Knee Raise', 'single_leg', 1, 'strength', 'glutes', ARRAY['step'], '["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.", "Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.", "Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."]'::jsonb),
('Crunches', 'Crunches', 'core', 1, 'strength', 'abdominals', ARRAY['body weight'], '["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.", "Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.", "While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.", "Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.", "After the one second contraction, begin to come down slowly again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Reverse_Crunch', 'Reverse Crunch', 'core', 1, 'strength', 'abdominals', ARRAY['body weight'], '["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.", "Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.", "While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.", "Hold the contraction for a second and move your legs back to the starting position while exhaling.", "Repeat for the recommended amount of repetitions."]'::jsonb),
('Dead_Bug', 'Dead Bug', 'core', 1, 'strength', 'abdominals', ARRAY['body weight'], '["Begin lying on your back with your hands extended above you toward the ceiling.", "Bring your feet, knees, and hips up to 90 degrees.", "Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.", "Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.", "Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.", "Stay tight and return the working leg to the starting position.", "Repeat on the opposite side, alternating until the set is complete."]'::jsonb),
('Plank', 'Plank', 'core', 1, 'timed', 'abdominals', ARRAY['body weight'], '["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."]'::jsonb),
('Side_Bridge', 'Side Bridge', 'core', 1, 'timed', 'abdominals', ARRAY['body weight'], '[]'::jsonb),
('Cross-Body_Crunch', 'Cross-Body Crunch', 'core', 1, 'strength', 'abdominals', ARRAY['body weight'], '["Lie flat on your back and bend your knees about 60 degrees.", "Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.", "Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.", "Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.", "Continue alternating in this manner until all prescribed repetitions are done."]'::jsonb),
('Oblique_Crunches_-_On_The_Floor', 'Oblique Crunches - On The Floor', 'core', 1, 'strength', 'abdominals', ARRAY['body weight'], '["Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.", "Place your left hand behind your head.", "Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.", "Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.", "Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise."]'::jsonb),
('Tuck_Crunch', 'Tuck Crunch', 'core', 1, 'strength', 'abdominals', ARRAY['body weight'], '["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.", "Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.", "Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.", "While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.", "Slowly begin to lower your torso back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."]'::jsonb);
INSERT INTO exercises (external_id,source,name,instructions,raw_data)
INSERT INTO equipments (name) SELECT DISTINCT unnest(gear) FROM core_seed ON CONFLICT (name) DO NOTHING;
INSERT INTO muscles (name) SELECT DISTINCT muscle FROM core_seed ON CONFLICT (name) DO NOTHING;
INSERT INTO exercise_equipments (exercise_id,equipment_id)
INSERT INTO exercise_muscles (exercise_id,muscle_id,muscle_role)
INSERT INTO recommendation_exercises (exercise_id,movement_pattern,difficulty,exercise_type,beginner_friendly,
